from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

root=Path(__file__).resolve().parents[3]
out=root/'docs/manual/por-rol'
out.mkdir(parents=True,exist_ok=True)
logo=root/'frontend/apps/admin-web/public/crece-impulso-logo.png'
modules={}
def add(key,title,path,steps,check):
    modules[key]=(title,path,steps.split('|'),check)
add('login','Entrar y renovar la contraseña','Pantalla de acceso','Ingresa con el correo de trabajo y tu contraseña.|Si aparece Renueva tu contraseña, escribe la actual y confirma una nueva distinta de la actual y de la anterior.|Comprueba tu nombre y sucursal. Abre el menú lateral y cierra sesión al terminar.', 'La contraseña del personal vence cada 15 días. Si no puedes renovarla, solicita asistencia al administrador. Ante un error de red, comprueba la conexión y reintenta.')
add('dash','Consultar el tablero','Inicio','Revisa la fecha operativa de Cancún y el alcance de la cuenta.|Consulta los indicadores visibles de grupos, trámites, créditos, cobros y cartera.|Abre el módulo asociado para identificar los registros que explican un total.', 'Los cobros del día se separan por medio y reflejan reversos. Para cuadrar efectivo físico, usa el corte de Caja.')
add('users','Administrar usuarios','Administración → Usuarios','Selecciona Crear usuario o abre el registro existente.|Captura nombre, correo, contraseña inicial cuando corresponda, rol, sucursal y estado de la cuenta.|Guarda y verifica con el usuario qué opciones aparecen después de volver a iniciar sesión.', 'Solo Super Admin administra cuentas. Asigna la sucursal operativa correcta. Al retirar acceso, revisa la cuenta y sus asignaciones de grupos antes de desactivarla.')
add('roles','Configurar roles y permisos','Administración → Roles y permisos','Abre un rol o selecciona Crear rol.|Marca únicamente las funciones requeridas para ese puesto.|Guarda y comprueba el menú y las operaciones con una cuenta de prueba del perfil.', 'Un permiso habilita una acción y el servidor también valida sucursal, grupo, estado y versión del registro. Conserva una cuenta de Super Admin operativa.')
add('promoters','Registrar y asignar promotores','Promotores','Comprueba que el colaborador tenga una cuenta activa, rol Promotor y sucursal asignada.|Usa Registrar promotor y selecciona la cuenta correspondiente.|Al crear un grupo, busca y elige un promotor registrado de esa sucursal.', 'El nombre de quien captura no determina la asignación. Cuando quien captura es Promotor, el sistema utiliza su propia asignación si es elegible.')
add('groups','Crear grupos y registrar el comité','Grupos solidarios','Busca el grupo por sucursal y nombre antes de crear otro. Usa su folio o identificador para distinguir homónimos.|Crea el grupo con nombre, sucursal y promotor elegible. Guarda antes de incorporar integrantes.|Abre el grupo y registra los cargos de Presidenta, Tesorera e integrantes conforme al acta.', 'Verifica que las personas correspondan al grupo y que el comité esté completo. Una solicitud de crédito requiere al menos tres participantes.')
add('clients','Capturar o corregir expedientes','Clientes → Capturar expediente','Consulta la CURP antes de capturar. Si existe, revisa sucursal, créditos y la opción de editar cuando esté habilitada.|Selecciona el grupo de la sucursal mediante búsqueda. Llena identidad, domicilio, familia, economía, referencias, créditos externos y declaraciones aplicables.|Guarda borrador. Si Gestión pidió una corrección, abre el expediente existente, corrige lo observado y vuelve a guardarlo.', 'El sistema asigna el folio al guardar. Captura el monto en Solicitudes de crédito. Si la CURP corresponde a otra sucursal o no tienes acceso, escala el caso a Gerencia.')
add('submit','Enviar expedientes y solicitar un crédito','Clientes y Solicitudes de crédito → Nueva solicitud','Verifica expedientes completos, comité, elegibilidad del grupo y ausencia de bloqueos por deuda u otro crédito abierto.|Envía los expedientes que correspondan. Abre Nueva solicitud y selecciona grupo, tasa común, límite por integrante y monto individual solicitado.|Revisa el total y las estimaciones. Presenta la solicitud a Gestión y conserva el folio para seguimiento.', 'Si Gestión devuelve una observación, corrige y envía los expedientes afectados, luego usa Reenviar a Gestión con una nota. Los montos originales se conservan.')
add('review','Revisar una solicitud en Gestión','Gestión de solicitudes → Revisión de Gestión','Busca por folio o grupo y abre cada integrante.|Coteja identidad, domicilio, referencias, visita, historial interno y documentos firmados. Registra evidencia u observaciones en cada comprobación.|Guarda avance. Para devolver, indica la comprobación observada y una nota general. Para enviar a autorización, verifica las seis comprobaciones por integrante y registra la nota general.', 'La evidencia se coteja en la operación. El estado de revisión habilita la etapa comercial. Si hay cambios simultáneos, recarga y vuelve a cotejar.')
add('proposal','Preparar la propuesta comercial','Autorización comercial → Detalle','Abre un crédito que Gestión remitió a autorización. Comprueba el solicitado de cada persona y la tasa conservada.|Captura los montos propuestos dentro de los límites. Selecciona por separado el medio de entrega del crédito y el de pagos semanales.|Revisa garantía, importe neto y cuota. Envía la propuesta a Coordinación Comercial. Si se devuelve, atiende las notas y presenta la propuesta revisada.', 'Comprueba que el solicitado se mantiene separado del aprobado. La propuesta queda en el historial.')
add('approve','Autorizar o devolver condiciones','Autorización comercial → Detalle','Revisa la propuesta vigente, las observaciones de Gestión y los datos de cada integrante.|Para devolver, escribe el motivo. Para autorizar, captura la fecha pactada del primer pago y revisa las 16 fechas con intervalos de siete días.|Confirma la autorización y revisa el estado aprobado antes de remitir a la sucursal para la entrega.', 'La fecha del primer pago queda vinculada a las condiciones autorizadas. Si la entrega se retrasa hasta esa fecha, escala el caso antes de intentar registrar la entrega.')
add('rates','Mantener el catálogo de tasas','Tasas','Busca una tasa o crea una entrada con nombre, ciclo, límites configurados y factor semanal por cada mil pesos.|Verifica los importes de muestra y guarda el estado activo cuando corresponda.|Coteja la selección de la tasa en una nueva solicitud.', 'Una tasa nueva o editada aplica a selecciones posteriores. Las condiciones guardadas en solicitudes anteriores se conservan.')
add('delivery','Registrar la entrega del crédito','Desembolsos y calendario','Abre el crédito aprobado y confirma las condiciones vigentes y el medio autorizado.|Coteja capital aprobado, garantía retenida y neto entregado. Registra la fecha real y los datos bancarios si la entrega es por depósito.|Confirma una vez realizada la entrega. Comprueba el estado Entregado y el calendario de 16 cuotas.', 'Usa la fecha pactada de solo lectura. En autorizaciones históricas sin primer vencimiento, captura la fecha cuando la pantalla lo solicite.')
add('payment','Registrar abonos y emitir comprobante','Cobros en caja → Abrir crédito','Confirma el folio, la sucursal, el saldo y la fecha de recepción. Selecciona el medio real de pago.|En depósito, coteja el comprobante y captura banco, folio y fecha. Desglosa quién aporta y a qué integrante se aplica cada importe.|Confirma el cobro y abre el ticket. Verifica importe, medio, folio y estado del QR antes de entregar el comprobante.', 'Puede registrar pagos parciales. El sistema cubre primero las cuotas exigibles desde la más antigua, luego mora y después cuotas futuras. Ante un error de conexión, consulta si el cobro quedó registrado antes de repetirlo.')
add('reverse','Revertir un pago registrado por error','Cobros en caja → Ver comprobante','Abre el comprobante original y coteja operación, medio e importe.|Con permiso de reverso, registra el motivo y confirma el reverso completo.|Comprueba el estado del comprobante, el saldo actualizado y el ajuste del corte cuando corresponda.', 'El sistema conserva el pago original y su trazabilidad. Cualquier devolución física de dinero se gestiona por el procedimiento de sucursal.')
add('closing','Cerrar y consultar caja','Cortes de caja','Selecciona la fecha de recepción y verifica tus cobros pendientes de cerrar en la sucursal.|Compara efectivo registrado y contado, y valida los depósitos por separado. Registra la explicación si existe diferencia.|Confirma el corte. Abre Reporte completo y usa Imprimir o guardar PDF. Gerencia puede consultar cortes conforme a su alcance.', 'El corte incluye los cobros del cajero que corresponde. Los reversos posteriores aparecen como ajustes separados de los totales originales.')
add('portfolio','Consultar cartera y atraso','Cartera y vencimientos','Busca por folio, grupo o sucursal. Filtra Todos, Con atraso, Vence hoy o Sin atraso.|Compara saldo total, cuotas pendientes, mora, monto exigible y días de atraso. Abre el estado de cuenta para revisar el detalle.|Descarga el CSV o abre Reportes para impresión para preparar el formato de cartera.', 'Exigible y atraso están incluidos en el saldo, evita sumarlos otra vez. El traslado formal a cartera vencida sigue pendiente. Los filtros de atraso operan sobre la consulta.')
add('statement','Revisar estados de cuenta y garantía','Detalle del crédito → Estado de cuenta o Garantía','Abre el estado de cuenta de un crédito entregado o liquidado y selecciona grupo o integrante.|Comprueba vencimientos, abonos, saldo, mora y aplicaciones de garantía. Usa Imprimir o guardar PDF o el Formato de referencia.|En Garantía consulta importe retenido, aplicado y disponible por persona.', 'La retención no es un abono. El saldo exigible incluye cuotas de hoy, atrasos y mora aplicable.')
add('guarantee','Aplicar la garantía retenida','Detalle del crédito → Garantía','Comprueba que haya llegado el vencimiento de la semana 16 y que exista saldo aplicable.|Revisa cuánto se aplicará a las cuotas de cada integrante. Registra el motivo y confirma con permiso comercial.|Comprueba el movimiento y el saldo nuevo. Para corregir una aplicación usa el ajuste disponible según permisos y estado.', 'La garantía cubre cuotas de la misma integrante. El remanente queda identificado y la mora se consulta aparte.')
add('profiles','Configurar datos documentales','Administración → Datos documentales por sucursal','Selecciona Empresa o sucursal.|Captura domicilio legal, representante, cargo, lugar de pago y lugar habitual de suscripción. Para una sucursal elige si hereda los datos generales.|Guarda, reabre y coteja que aparece el origen de los datos esperado.', 'La fecha de suscripción corresponde a la firma real. Las versiones emitidas conservan los datos con los que se generaron.')
add('docs','Generar e imprimir documentos','Expediente o crédito autorizado → Documentos','En el expediente genera solicitud o acta de instalación. En crédito autorizado genera acta de autorización, calendario o los formatos de referencia de contrato y pagaré.|Abre la versión generada, coteja folio, integrantes y datos visibles. Usa Imprimir o guardar PDF. Adjunta el PDF firmado únicamente en los formatos que permiten adjuntarlo.|Para reimprimir, elige la versión en el historial. En la impresión del contrato, entrega de forma individual el anexo de acceso cuando se genere.', 'Contrato y pagaré de referencia están en revisión. Las diferencias de condiciones entre el texto de referencia y la operación se revisan antes de formalizar. Reimprimir conserva versiones y no recupera claves.')
add('reports','Preparar reportes para impresión','Reportes para impresión','Elige cartera, estado de cuenta, relación de fichas de depósito, bitácora o agenda según el permiso.|Selecciona filtros, crédito, integrante o semana según el formato. Pulsa Preparar reporte y verifica el resultado en la vista previa.|Imprime o guarda PDF. Completa citas y compromisos en los espacios manuales que correspondan.', 'Los depósitos vigentes se muestran separados de reversos. Los campos sin dato registrado quedan indicados. El corte completo y los tickets se imprimen desde sus módulos.')
add('access','Entregar y recuperar acceso a clientes','Accesos de clientes','Busca la CURP o el número de cliente completo. Confirma el folio y verifica presencialmente la identidad.|Selecciona la opción de activación o recuperación de cuenta existente. Genera el código y entrégalo únicamente a la persona titular.|Indica cómo abrir el flujo de activación o recuperación en Client App. Si el código venció, valida nuevamente la identidad para emitir otro.', 'Una contraseña temporal entregada en el anexo del contrato se usa en Entrar y debe cambiarse. Entrega solo el renglón de la titular, nunca la hoja completa.')
add('messages','Enviar y consultar mensajes','Mensajes → Enviar mensaje','Elige Cliente o Colaborador. Selecciona la sucursal y busca al destinatario escribiendo su nombre.|Captura asunto y mensaje. Revisa destinatario y texto antes de confirmar el envío.|Consulta Mensajes para los avisos de tu cuenta. La entrega push depende del dispositivo y de la configuración del servicio.', 'Evita incluir contraseñas o información sensible en el asunto. Los clientes pueden revisar su bandeja desde la app.')
add('inbox','Consultar avisos','Mensajes','Abre la bandeja desde el menú.|Actualiza y revisa los avisos. Marca como leído cuando corresponda.', 'Para mensajes sobre un crédito, localiza el folio en el módulo correspondiente y verifica la información registrada.')
add('activate','Activar o recuperar tu acceso','Client App → Pantalla de acceso','Acude a la sucursal con tu identificación y recibe el código de activación o recuperación.|En la app abre Configura tu acceso. Captura el código y la contraseña nueva, confírmala y usa Guardar mi acceso.|Vuelve a Entrar e inicia sesión con tu número de cliente y la nueva contraseña.', 'Usa al menos 12 caracteres con letras y números. Si el código vence o ya fue utilizado, pide asistencia a tu sucursal.')
add('clientlogin','Entrar con tu número de cliente','Client App → Entrar','Escribe el número de cliente completo y la contraseña personal. Si recibiste una contraseña temporal, escríbela en este mismo formulario.|Si aparece Elige tu contraseña personal, introduce la temporal y confirma la nueva. Guarda y verifica tu nombre, folio y sucursal.|Usa Cerrar sesión al terminar, sobre todo si compartes el dispositivo.', 'La clave temporal de contrato vence a los siete días. Si pierdes el acceso, solicita recuperación presencial.')
add('clientbalance','Consultar tu crédito y los pagos semanales','Inicio → Tu crédito activo → Estado de cuenta','Consulta saldo, próxima fecha, atrasos y las secciones Condiciones y entrega y Detalle de mora cuando estén disponibles.|En Estado de cuenta, elige Personal para tus cuotas o Grupo para los totales semanales. Desliza la tabla para ver todas las columnas.|Lee la fecha, monto pactado, aplicado, pendiente y estado. Verde indica pagada, amarillo incompleta sin vencer y rojo vencida con saldo. Las cuotas futuras sin abono y las que vencen hoy se muestran en estado neutro.', 'Si tu abono fue de $500 y la cuota era de $800, quedan $300 de esa cuota antes de la mora que corresponda. Si no hay crédito activo o un dato no coincide, consulta a tu sucursal.')
add('ticket','Consultar un comprobante de pago','Inicio → Comprobantes → Ver ticket QR','Busca el pago registrado y pulsa Ver ticket QR.|Coteja folio, fecha, importe y estado. Si necesitas ver más movimientos, usa Cargar comprobantes.|Si un ticket figura revertido o falta un pago, lleva tu comprobante a Caja para revisión.', 'El QR verifica el registro de un pago recibido. Realiza los pagos por el medio acordado con tu sucursal.')
add('clientmsg','Consultar mensajes y activar recordatorios','Inicio → Mis mensajes y Recordatorios','Abre Mis mensajes, actualiza y marca los avisos leídos cuando corresponda.|En Recordatorios, usa Activar recordatorios y autoriza las notificaciones del dispositivo. Puedes desactivarlos en la misma sección.|Consulta la bandeja y el calendario de pagos si un aviso no aparece.', 'Los recordatorios pueden incluir avisos del día anterior, del vencimiento, del pago recibido y del día siguiente. Las notificaciones requieren los permisos y la configuración del dispositivo y del servicio.')
add('connect','Resolver problemas de conexión','Pantalla de acceso → Probar conexión','Comprueba tu conexión a internet y pulsa Probar conexión. Si el servidor responde pero el acceso falla, revisa número de cliente y contraseña.|En Configuración del dispositivo cambia IP o dominio solo con la dirección que te indique soporte. Prueba la conexión, guarda la dirección autorizada y vuelve al acceso. Guardar una dirección distinta cierra la sesión.|Si no puedes entrar después de probar la conexión, comunica la pantalla y el mensaje a tu sucursal. Mantén en privado tu código y contraseña.', 'Usar dirección inicial restaura la dirección de la instalación. Consulta a soporte si el dispositivo tiene una dirección de pruebas.')
add('case','Ejemplo de un ciclo completo','Solicitud → Gestión → Comercial → Desembolso → Caja','Para un grupo de tres personas, registra $10,000 solicitados y aprobados por integrante. Con factor Cobre de $80 por cada mil, cada cuota es de $800 y el total individual es de $12,800 en 16 semanas.|Comercial autoriza el primer vencimiento. En la entrega se registra $1,000 de garantía y $9,000 netos por persona. El grupo recibe $27,000 y su calendario suma $38,400.|Si una integrante abona $500 en una cuota de $800 y nadie cubre el faltante, quedan $300. Con la política semanal autorizada, el primer tramo de atraso genera $30 de mora. Un abono posterior cambia la base de los siguientes tramos.|Caja emite el ticket y clasifica el medio de pago en el corte. Comercial revisa la garantía al llegar la semana 16.', 'Ejemplo ficticio. Contrasta el estado de cuenta, el reporte de cartera, el ticket y el corte con los mismos folios. Las condiciones del crédito definen la mora aplicable.')
add('support','Resolver incidencias de operación','Módulo donde apareció el aviso','Si falta una opción, revisa el rol y la sucursal asignados. Si no aparece un crédito, verifica su etapa, los filtros y el alcance.|Si una operación queda en duda tras perder conexión, recarga el registro y verifica historial, folio y estado antes de reenviar.|Si dos usuarios editaron el mismo trámite, abre la versión actual y vuelve a cotejar los datos antes de confirmar.|Entrega a soporte el módulo, folio, hora y texto del error. Mantén en privado las contraseñas, códigos y datos personales innecesarios.', 'Escala discrepancias de saldo a Caja o Gerencia y bloqueos de autorización a Comercial. Usa el historial para documentar la resolución.')
add('audit','Auditar la operación por sucursal','Inicio → Cartera y vencimientos → Cortes de caja','Comprueba el filtro de sucursal, la fecha operativa y los folios del caso.|Cruza saldos y atrasos con estados de cuenta. Para cobros, coteja el comprobante, el medio y el corte correspondiente.|Si hay un reverso posterior, comprueba su motivo y los ajustes separados. Revisa depósitos y efectivo contado por separado.', 'Una consulta de cartera representa saldos actuales. El corte conserva los totales originales del cierre.')
# Edición 2.0 del 19 de noviembre de 2026. Procedimientos verificados contra las pantallas.
add('idle','Sesión y cierre por inactividad','Admin Web y apps móviles','Guarda los cambios antes de dejar de trabajar. La sesión termina al cumplir 30 minutos sin usar teclado, puntero o pantalla táctil.|Al volver de segundo plano o desbloquear el teléfono, comprueba si aparece el aviso de sesión terminada. Ingresa nuevamente con contraseña o con el acceso biométrico que hayas activado.|Después de ingresar, abre el registro y revisa lo que quedó guardado antes de continuar. Cierra sesión manualmente al finalizar en un equipo compartido.', 'Las consultas automáticas y notificaciones no mantienen abierta la sesión. El correo o número recordado y la preferencia biométrica se conservan. Los formularios sin guardar pueden perderse; la caducidad de sesión es distinta de la renovación de contraseña del personal cada 15 días.')
add('biometric','Recordar el acceso y activar biometría','Apps móviles → Pantalla de acceso y Configuración del dispositivo','Escribe tu correo en Colaboradores o tu número de cliente en Clientes. Marca Recordar correo o Recordar número de cliente si quieres conservarlo en ese dispositivo.|En la app nativa, marca Activar acceso con Face ID, Touch ID, huella o reconocimiento facial, según la opción disponible. Entra primero con tu contraseña y acepta la comprobación del teléfono.|Si tu contraseña es temporal o está vencida, cámbiala primero; después vuelve a ingresar con la nueva y activa la biometría.|En un acceso posterior, elige Entrar con Face ID o el método disponible, o usa el formulario de contraseña. Si cancelas, no se abre la sesión.|Para retirarlo, pulsa Eliminar acceso biométrico guardado en el acceso o en Configuración del dispositivo. Para olvidar el identificador, desmarca Recordar correo o Recordar número de cliente.', 'La preferencia biométrica es independiente del identificador recordado. Solo úsala en un dispositivo personal. En navegador se utiliza contraseña; la biometría requiere una versión nativa actualizada y compatible. Cambiar de servidor elimina el acceso guardado del servidor anterior. Cerrar sesión conserva la opción biométrica; eliminar el acceso la retira. Las fotos y huellas las administra el teléfono, no la sucursal.')
add('branches','Crear y mantener sucursales','Administración → Sucursales','Busca por nombre, localidad o código y filtra Activas, Inactivas o Todas.|Para crear, pulsa Nueva sucursal. Escribe el nombre y, cuando corresponda, localidad, teléfono, correo y domicilio operativo. Guarda y comprueba el código asignado.|Para corregir, abre Editar sucursal, cambia los datos y guarda. Si otro usuario editó el registro, actualiza antes de repetir la operación.|Para desactivar, resuelve las solicitudes y créditos abiertos y reasigna o desactiva a los usuarios activos de la sucursal. Después cambia el estado en Editar sucursal.|Si se perdió la respuesta al guardar, utiliza el reintento del mismo registro y comprueba la lista antes de crear otro.', 'Solo Super Admin y Gerente General administran este catálogo. El UUID y el código de folios son permanentes; cambiar el nombre no los modifica. No se elimina el historial. Los datos legales del contrato y pagaré se mantienen aparte en Datos documentales, administrados por Super Admin.')
add('cashmovements','Consultar cobros y depósitos','Cobros y depósitos o Caja central','Selecciona Desde, Hasta, sucursal permitida y Medio del cobro. Escribe una referencia bancaria, folio de crédito, nombre de grupo o cajero para afinar la búsqueda.|Pulsa Consultar y coteja efectivo recibido, depósitos registrados, reversos y neto. Revisa fecha, crédito, grupo, cajero, ficha bancaria y corte original en el detalle.|Si tienes permiso de cobro, usa Registrar cobro o depósito para abrir el flujo de Caja y distribuir el importe. Ver comprobante abre el ticket cuando tu permiso lo permite.|Descarga Todos los movimientos CSV para obtener todas las páginas del filtro, o Imprimir resumen para el consolidado.', 'El filtro se conserva al recargar. Los cobros se agrupan por fecha de recepción y los reversos por fecha del ajuste. El corte original se conserva. Capturar una ficha bancaria no verifica automáticamente el depósito con el banco. Los permisos de consulta no habilitan captura ni reversos.')
add('portfolio','Consultar cartera ordinaria y recuperación','Cartera y vencimientos y Reportes para impresión','Busca por folio, grupo o sucursal y selecciona cartera Ordinaria, Recuperación o Todas según la pantalla. Combina los filtros de atraso que correspondan.|Consulta cuotas, mora, saldo, exigible y días de atraso. Abre el estado de cuenta para verificar los movimientos.|Descarga el CSV o prepara el reporte de cartera con la clasificación seleccionada. Para conciliación general revisa Todas.', 'Recuperación separa créditos de la cartera ordinaria y conserva la deuda en el consolidado. El traslado no liquida ni elimina el crédito. Los abonos no lo reincorporan automáticamente. Exigible y atraso forman parte del saldo: evita sumarlos de nuevo.')
add('followup','Registrar observaciones de cobranza','Cartera → Seguimiento y Observaciones de cobranza','Localiza el crédito y abre Seguimiento. Revisa la clasificación y la situación por integrante.|Selecciona la integrante y captura una observación clara sobre visita, llamada, compromiso o aclaración. Guarda y comprueba autor y fecha en el historial.|Si se perdió la respuesta, reintenta la misma observación. Verifica que figure una sola vez.|En Observaciones de cobranza, filtra sucursal, periodo y búsqueda según la pantalla. Recarga para consultar el historial guardado.', 'Super Admin, Gerente General, Gerente y Cobranza disponen inicialmente del seguimiento, según su alcance. Una observación no registra dinero, no altera saldos ni sustituye un cobro de Caja. No agregues contraseñas ni información personal innecesaria.')
add('recovery','Trasladar o reincorporar cartera','Crédito → Seguimiento','Como Super Admin o Gerente General, verifica que el crédito tenga atraso antes de trasladarlo.|Pulsa Trasladar a recuperación, escribe el motivo obligatorio y confirma. Comprueba el cambio y su historial.|Verifica que no aparezca en el reporte ordinario y que se conserve en Recuperación y en Todas.|Para devolverlo, abre Seguimiento, selecciona Reincorporar a ordinaria, registra el motivo y confirma.', 'El traslado es manual y exclusivo de Super Admin o Gerente General. Gerencia de sucursal y Cobranza registran seguimiento, pero no autorizan esta clasificación. Los abonos siguen permitidos y no cambian automáticamente la cartera.')
add('printpayment','Elegir formato de comprobante e impresora','Cobros en caja → Comprobante → Impresión','Abre el comprobante del pago y coteja el folio y el estado.|Selecciona Carta con dos copias o el formato de ticket de 80 o 58 mm, según el papel de tu impresora.|Pulsa Imprimir. En el diálogo del navegador o del sistema elige la impresora, el tamaño y la escala adecuados; también puedes Guardar como PDF.|Revisa la vista previa y entrega la copia correspondiente. Si hay muchos conceptos, comprueba todas las páginas o segmentos antes de imprimir.', 'La preferencia de formato se guarda en ese dispositivo. El navegador no asigna automáticamente una impresora física. La impresión no modifica el importe ni genera un cobro nuevo. El QR permite consultar la autenticidad y estado del registro; conserva el original si aparece un reverso.')
add('offline','Preparar y corregir expedientes sin conexión','Colaboradores → Trabajo sin conexión','Con internet, entra con tu cuenta y prepara el espacio y los expedientes a los que tienes acceso. Define la clave local del espacio cuando se solicite; es distinta de tu contraseña de usuario.|Sin internet, abre Trabajo sin conexión, selecciona el espacio y desbloquéalo con la clave local. Realiza las altas o correcciones permitidas y usa Guardar en dispositivo.|Si pasan 30 minutos sin interacción, el espacio se bloquea y solicita otra vez la clave local. Los datos guardados y la cola pendiente permanecen; los cambios sin guardar pueden perderse.|Cuando recuperes conexión, vuelve a autenticarte si la sesión venció y sincroniza con la cuenta que preparó el espacio. Revisa los conflictos; selecciona los datos que deben conservarse y guarda antes de reenviar.', 'El trabajo offline no habilita cobros en campo. Los documentos se generan e imprimen desde Admin Web. No borres la aplicación ni su almacenamiento si tienes registros pendientes de sincronizar. Una corrección local no se considera recibida por oficina hasta confirmar su sincronización.')
add('staffapp','Usar la app de colaboradores','Colaboradores → Menú lateral','Entra con tu correo de trabajo y contraseña. Activa el recordatorio o la biometría si deseas y el dispositivo es personal.|Abre el menú y revisa Mi jornada, Grupos, Expedientes, Mis mensajes y Mi acceso. Los módulos operativos adicionales aparecen según los permisos y alcance de tu cuenta.|Captura y corrige los datos autorizados, comprueba folio, grupo y sucursal y guarda antes de cambiar de pantalla.|Para operaciones de revisión, autorización, entrega, Caja o administración utiliza solo las opciones que tu rol habilita. Para generar documentación vuelve a Admin Web.|Si cambia la dirección del servidor, pide la dirección autorizada a soporte y actualízala en Configuración del dispositivo. Vuelve a ingresar para validar tu cuenta.', 'Ser usuario móvil no amplía los permisos ni el alcance de sucursal. El promotor no cobra en campo. Los módulos online requieren internet; las correcciones preparadas se gestionan en Trabajo sin conexión.')
add('bankaudit','Consultar cortes y contrastar fichas','Cortes de caja y Caja central','Selecciona fecha, sucursal y cajero según el alcance de la consulta.|Abre el corte disponible y revisa por separado depósitos, efectivo y ajustes por reverso.|Contrasta la referencia bancaria del movimiento con el soporte recibido por Caja. Comunica diferencias al responsable de sucursal sin modificar pagos ni cortes.', 'El rol Bancos consulta y audita; no cierra el corte de otro cajero, no captura pagos ni autoriza reversos. Los ajustes posteriores se muestran aparte de los importes originales.')
# Mejores rutas de atención y referencias actuales.
def manual(slug,role,intro,keys,scope):
    d=Document()
    sec=d.sections[0]
    sec.page_width=Inches(8.5);sec.page_height=Inches(11)
    sec.top_margin=Inches(.62); sec.bottom_margin=Inches(.60)
    sec.left_margin=sec.right_margin=Inches(.75)
    normal=d.styles['Normal']; normal.font.name='Calibri'; normal.font.size=Pt(11)
    normal.paragraph_format.space_after=Pt(4)
    normal.paragraph_format.line_spacing=1.05
    normal.paragraph_format.widow_control=True
    for st in d.styles:
        for x in list(st.element.iter(qn('w:pBdr'))): x.getparent().remove(x)
    for n,size in [('Title',27),('Heading 1',17),('Heading 2',13)]:
        x=d.styles[n];x.font.name='Calibri';x.font.size=Pt(size)
        x.font.color.rgb=RGBColor.from_string('000000')
        x.paragraph_format.space_before=Pt(8);x.paragraph_format.space_after=Pt(4)
    footer=sec.footer.paragraphs[0];footer.alignment=2
    footer.add_run('Crece Impulso   •   '+role+'   •   ').font.size=Pt(9)
    fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');footer._p.append(fld)
    d.add_picture(str(logo),width=Inches(2.2))
    d.add_paragraph('Manual de '+role,'Title')
    d.add_paragraph('Edición 2.0 | 19 de noviembre de 2026')
    d.add_paragraph(intro)
    p=d.add_paragraph();p.add_run('Alcance. ').bold=True;p.add_run(scope)
    if slug=='Super-Admin':
        d.add_heading('Flujo de trabajo',1)
        d.add_paragraph('Promotor prepara expedientes. Gerencia envía la solicitud. Gestión verifica. Gerencia propone condiciones. Coordinación Comercial autoriza. Sucursal entrega. Caja registra cobros y cortes. Comercial aplica garantía cuando corresponda.')
        d.add_paragraph('Los perfiles de esta edición describen los permisos iniciales del sistema. Los roles personalizados se verifican en Administración. El alcance general corresponde a Super Admin y Gerente General.')
    for key in keys:
        title,path,steps,check=modules[key]
        d.add_heading(title,1)
        p=d.add_paragraph(path);p.runs[0].font.color.rgb=RGBColor.from_string('535866');p.paragraph_format.keep_with_next=True
        for i,step in enumerate(steps,1):
            p=d.add_paragraph();p.paragraph_format.left_indent=Inches(.24);p.paragraph_format.first_line_indent=Inches(-.24)
            p.add_run(str(i)+'. ').bold=True;p.add_run(step)
            p.paragraph_format.keep_together=True
        p=d.add_paragraph();p.add_run('Verificación. ').bold=True;p.add_run(check);p.paragraph_format.keep_together=True
    d.core_properties.title='Manual de '+role;d.core_properties.author='Crece Impulso'
    d.save(out/f'Manual-{slug}.docx')
    lines=[f'# Manual de {role}', '', '**Edición 2.0 | 19 de noviembre de 2026**', '', intro, '', '**Alcance.** '+scope]
    for key in keys:
        title,path,steps,check=modules[key]
        lines+=['',f'## {title}', '', '**Dónde:** '+path, '']
        lines += [f'{i}. {step}' for i,step in enumerate(steps,1)]
        lines += ['', '**Verificación.** '+check]
    (out/f'Manual-{slug}.md').write_text('\n'.join(lines)+'\n')
